#include <algorithm>

using namespace std;

class Interval
{
public:
    int l, r;
    Interval(int l, int r) : l(l), r(r) {}
};

static int Next()
{
    int c;
    int res = 0;
    do
    {
        c = getchar();
        if (c == EOF)
            return res;
    } while (c < '0' || c > '9');
    res = c - '0';
    while (true)
    {
        c = getchar();
        if (c < '0' || c > '9')
            return res;
        res = res * 10 + (c - '0');
    }
}

static int BinarySearch(const vector<Interval*>& list, Interval* value)
{
    int lo = 0, hi = (int)list.size() - 1;
    while (lo <= hi)
    {
        int mid = lo + (hi - lo) / 2;
        if (list[mid]->l == value->l) return mid;
        if (list[mid]->l < value->l) lo = mid + 1;
        else hi = mid - 1;
    }
    return ~lo;
}

static bool Find(vector<Interval*>* dp, Interval* value, int index)
{
    for (int i = index - 2; i >= 0; i--)
    {
        int ind = BinarySearch(dp[i], value);
        if (ind < 0)
        {
            ind = (~ind) - 1;
            if (ind > 0 && dp[i][ind]->r >= value->r)
            {
                return true;
            }
        }
        else
        {
            if (dp[i][ind]->r >= value->r)
                return true;
        }
    }
    return false;
}

int main()
{
    int n = Next();
    int k = Next();

    vector<int> l(k), r(k);
    for (int i = 0; i < k; i++)
    {
        l[i] = Next();
        r[i] = Next();
    }

    int size = 2 * k + 1;
    vector<Interval*>* dp = new vector<Interval*>[size];

    dp[0].push_back(new Interval(0, 0));

    int prev = 0;
    for (int i = 0; i < k; i++)
    {
        vector<Interval*>* next = new vector<Interval*>[size];

        int delta = l[i] - prev;
        for (int index = 0; index < size; index++)
        {
            if (index % 2 == 0)
            {
                vector<Interval*>& t = dp[index];
                for (auto interval : t)
                {
                    interval->l += delta;
                    interval->r += delta;
                }
            }
        }
        delta = r[i] - l[i];
        for (int ii = 0; ii < size; ii++)
        {
            if (ii % 2 == 0)
            {
                for (auto interval : dp[ii])
                {
                    next[ii].push_back(new Interval(interval->l + delta, interval->r + delta));
                    next[ii + 1].push_back(new Interval(interval->l, interval->r + delta));
                    next[ii + 2].push_back(new Interval(interval->l, interval->r + delta));
                }
            }
            else
            {
                for (auto interval : dp[ii])
                {
                    next[ii].push_back(new Interval(interval->l, interval->r));
                    next[ii + 1].push_back(new Interval(interval->l, interval->r + delta));
                    next[ii + 2].push_back(new Interval(interval->l, interval->r + delta));
                }
            }
        }

        prev = r[i];
        for (int index = 0; index < size; index++)
        {
            dp[index].clear();

            Interval* pr = nullptr;

            vector<Interval*> sorted = next[index];
            stable_sort(sorted.begin(), sorted.end(), [](Interval* a, Interval* b) {
                return a->l < b->l;
            });

            for (auto interval : sorted)
            {
                if (interval->l > n)
                    break;
                if (pr != nullptr && pr->r >= interval->l)
                {
                    pr->r = max(pr->r, interval->r);
                }
                else
                {
                    if (pr != nullptr && !Find(dp, pr, index))
                        dp[index].push_back(pr);
                    pr = interval;
                }
            }
            if (pr != nullptr && !Find(dp, pr, index))
                dp[index].push_back(pr);
        }

        delete[] next;
    }

    {
        int delta = 2 * n - prev;
        for (int index = 0; index < size; index++)
        {
            if (index % 2 == 0)
            {
                vector<Interval*>& t = dp[index];
                for (auto interval : t)
                {
                    interval->l += delta;
                    interval->r += delta;
                }
            }
        }
    }

    for (int i = 0; i < size; i++)
    {
        for (auto interval : dp[i])
        {
            if (interval->l <= n && interval->r >= n)
            {
                printf("Full\n%d\n", i);
                delete[] dp;
                return 0;
            }
        }
    }

    printf("Hungry\n");
    delete[] dp;
    return 0;
}
